'use strict';

// MODULES //

var copysignf = require( '@stdlib/math/base/special/copysignf' );
var sincosf = require( '@stdlib/math/base/special/sincosf' ).assign;
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var expf = require( '@stdlib/math/base/special/expf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );


// VARIABLES //

var WORKSPACE = [ 0.0, 0.0 ];


// MAIN //

/**
* Evaluates the exponential function for a single-precision complex floating-point number and assigns results to a provided output array.
*
* @param {number} re - real component
* @param {number} im - imaginary component
* @param {Collection} out - output array
* @param {integer} strideOut - stride length
* @param {NonNegativeInteger} offsetOut - starting index
* @returns {Collection} output array
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var out = assign( 0.0, 0.0, new Float32Array( 2 ), 1, 0 );
* // returns <Float32Array>[ 1.0, 0.0 ]
*/
function assign( re, im, out, strideOut, offsetOut ) {
	var e;

	if ( isnanf( re ) ) {
		out[ offsetOut ] = NaN;
		out[ offsetOut+strideOut ] = ( im === 0.0 ) ? im : NaN;
		return out;
	}
	if ( isInfinitef( im ) ) {
		if ( re === PINF ) {
			out[ offsetOut ] = NINF;
			out[ offsetOut+strideOut ] = NaN;
			return out;
		}
		if ( re === NINF ) {
			out[ offsetOut ] = -0.0;
			out[ offsetOut+strideOut ] = copysignf( 0.0, im );
			return out;
		}
		out[ offsetOut ] = NaN;
		out[ offsetOut+strideOut ] = NaN;
		return out;
	}
	e = expf( re );
	if ( im === 0.0 ) {
		out[ offsetOut ] = e;
		out[ offsetOut+strideOut ] = im;
		return out;
	}
	sincosf( im, WORKSPACE, 1, 0 );
	out[ offsetOut ] = f32( WORKSPACE[ 1 ] * e );
	out[ offsetOut+strideOut ] = f32( WORKSPACE[ 0 ] * e );
	return out;
}


// EXPORTS //

module.exports = assign;
